<template>
  <view class="page">
    <block v-if="!isLogin">
      <view class="login-box">
        <view class="login-title">成为 Goat 会员</view>
        <view class="login-desc">登录后可订场、查看余额和会员卡</view>
        <button class="login-btn" @tap="goLogin">去登录</button>
      </view>
    </block>
    <block v-else>
      <view class="head">
        <image class="avatar" :src="avatarUrl || '/static/images/avatar.png'" mode="aspectFill"></image>
        <view class="name">{{ nickName }}</view>
        <view class="since" v-if="phone">{{ phone }}</view>
        <view class="since muted">山羊Goat网球馆会员</view>
        <view class="edit-btn" @tap="openEdit">修改头像昵称</view>
      </view>
      <view class="edit-mask" v-if="editing" @tap="editing=false">
        <view class="edit-card" @tap.stop>
          <view class="edit-title">修改资料</view>
          <button class="avatar-btn" open-type="chooseAvatar" @chooseavatar="onChooseAvatar">
            <image class="avatar" :src="editAvatar || avatarUrl || '/static/images/avatar.png'" mode="aspectFill" />
          </button>
          <input class="edit-input" type="nickname" placeholder="输入昵称" :value="editNick" @input="onNick" @blur="onNick" />
          <button class="save-btn" :loading="saving" @tap="saveProfile">保存</button>
        </view>
      </view>

      <view class="wallet">
        <view class="w-item">
          <view class="w-lab">现金余额</view>
          <view class="w-num">¥{{ Number(balance).toFixed(2) }}</view>
          <view class="w-tip">订场可直接抵扣</view>
        </view>
        <view class="w-item">
          <view class="w-lab">积分</view>
          <view class="w-num">{{ points || 0 }}</view>
          <view class="w-tip">暂不抵扣</view>
        </view>
      </view>

      <view class="triple">
        <view class="t-item" @tap="goMyCards">
          <image class="t-ico" src="/static/images/ui/ico-card.png"></image>
          <view class="t-n">卡券</view>
        </view>
        <view class="t-item" @tap="goMyBooking">
          <image class="t-ico" src="/static/images/ui/ico-book.png"></image>
          <view class="t-n">我的预约</view>
        </view>
        <view class="t-item" @tap="goMyCards">
          <image class="t-ico" src="/static/images/ui/ico-member.png"></image>
          <view class="t-n">会员卡</view>
        </view>
      </view>

      <view class="menu">
        <view class="menu-row" @tap="goMyBooking">
          <image class="m-ico" src="/static/images/tab/rank-on.png"></image>
          <text class="m-name">订单中心</text>
          <text class="en">MY ORDERS</text>
          <text class="arrow">›</text>
        </view>
        <view class="menu-row" @tap="goMyEval">
          <image class="m-ico" src="/static/images/tab/rank-on.png"></image>
          <text class="m-name">我的评测</text>
          <text class="en">MY EVALUATION</text>
          <text class="arrow">›</text>
        </view>
        <view class="menu-row" @tap="goMyCards">
          <image class="m-ico" src="/static/images/tab/shop-on.png"></image>
          <text class="m-name">我的会员卡</text>
          <text class="en">MY CARDS</text>
          <text class="arrow">›</text>
        </view>
        <view class="menu-row" v-if="role === 'coach'" @tap="goCoachWorkbench">
          <image class="m-ico" src="/static/images/tab/book-on.png"></image>
          <text class="m-name">教练工作台</text>
          <text class="en">WORKBENCH</text>
          <text class="arrow">›</text>
        </view>
        <view class="menu-row" @tap="comingSoon">
          <image class="m-ico" src="/static/images/tab/mine-on.png"></image>
          <text class="m-name">个人资料</text>
          <text class="en">PERSONAL INFO</text>
          <text class="arrow">›</text>
        </view>
        <view class="menu-row" @tap="comingSoon">
          <image class="m-ico" src="/static/images/tab/home-on.png"></image>
          <text class="m-name">联系客服</text>
          <text class="en">CONTACT</text>
          <text class="arrow">›</text>
        </view>
      </view>
      <view class="logout" @tap="logout">退出登录</view>
    </block>
    <app-tabbar :current="2" />
  </view>
</template>

<script>
import AppTabbar from '@/components/app-tabbar.vue'
import { callCloud } from '@/utils/api'
export default {
  components: { AppTabbar },
  data() {
    return {
      isLogin: false,
      avatarUrl: '',
      nickName: '',
      phone: '',
      role: 'user',
      balance: 0,
      points: 0,
      editing: false,
      editNick: '',
      editAvatar: '',
      saving: false
    }
  },
  onShow() {
    try { uni.hideTabBar({ animation: false }) } catch (e) {}
    this.checkLoginStatus()
    if (this.isLogin) this.loadWallet()
  },
  methods: {
    checkLoginStatus() {
      var nickName = uni.getStorageSync('nickName') || ''
      var phone = uni.getStorageSync('phone') || ''
      if (nickName || phone) {
        this.isLogin = true
        this.avatarUrl = uni.getStorageSync('avatarUrl') || ''
        this.nickName = nickName || '会员'
        this.phone = phone
        this.role = uni.getStorageSync('role') || 'user'
        this.balance = Number(uni.getStorageSync('balance') || 0)
        this.points = Number(uni.getStorageSync('points') || 0)
      } else {
        this.isLogin = false
      }
    },
    loadWallet() {
      var that = this
      wx.cloud.callFunction({
        name: 'userApi',
        data: {
          action: 'getWallet',
          userId: uni.getStorageSync('userDocId') || '',
          phone: that.phone || ''
        },
        success: function (res) {
          var r = res.result || {}
          if (!r.ok) return
          that.balance = Number(r.balance) || 0
          that.points = Number(r.points) || 0
          uni.setStorageSync('balance', that.balance)
          uni.setStorageSync('points', that.points)
        }
      })
    },
    goLogin() { uni.navigateTo({ url: '/pages/login/login' }) },
    goMyBooking() { uni.navigateTo({ url: '/pages/mybooking/mybooking' }) },
    goMyEval() { uni.navigateTo({ url: '/pages/my-eval/my-eval' }) },
    goMyCards() { uni.navigateTo({ url: '/pages/mycards/mycards' }) },
    goCoachWorkbench() { uni.navigateTo({ url: '/pages/coach-workbench/coach-workbench' }) },
    comingSoon() { uni.showToast({ title: '功能即将上线', icon: 'none' }) },

    openEdit() {
      this.editNick = this.nickName || ''
      this.editAvatar = this.avatarUrl || ''
      this.editing = true
    },
    onChooseAvatar(e) { this.editAvatar = (e.detail && e.detail.avatarUrl) || this.editAvatar },
    onNick(e) { this.editNick = ((e.detail && e.detail.value) || '').trim() },
    async saveProfile() {
      if (!this.editNick) { uni.showToast({ title: '请填写昵称', icon: 'none' }); return }
      this.saving = true
      try {
        const res = await callCloud({
          name: 'login',
          data: {
            action: 'register',
            phone: this.phone,
            nickName: this.editNick,
            avatarUrl: this.editAvatar,
            openid: uni.getStorageSync('openid') || ''
          }
        })
        const result = res.result || {}
        if (!result.ok) { uni.showToast({ title: result.msg || '保存失败', icon: 'none' }); return }
        this.nickName = result.nickName || this.editNick
        this.avatarUrl = result.avatarUrl || this.editAvatar
        uni.setStorageSync('nickName', this.nickName)
        uni.setStorageSync('avatarUrl', this.avatarUrl)
        this.editing = false
        uni.showToast({ title: '已保存', icon: 'success' })
      } catch (e) {
        uni.showToast({ title: '保存失败', icon: 'none' })
      } finally { this.saving = false }
    },
    logout() {
      var that = this
      uni.showModal({
        title: '提示',
        content: '确定要退出登录吗？',
        success: function (res) {
          if (!res.confirm) return
          ;['avatarUrl','nickName','openid','userId','userDocId','phone','role','balance','points','venue_id','venue_name'].forEach(function (k) {
            uni.removeStorageSync(k)
          })
          that.isLogin = false
          that.balance = 0
          that.points = 0
        }
      })
    }
  }
}
</script>

<style>
.page { min-height: 100vh; background: #f4f2ee; padding-bottom: 180rpx; }
.login-box { margin: 120rpx 40rpx; background: #fff; border-radius: 24rpx; padding: 80rpx 40rpx; text-align: center; }
.login-title { font-size: 40rpx; font-weight: 700; color: #1e4870; }
.login-desc { font-size: 26rpx; color: #999; margin: 16rpx 0 48rpx; }
.login-btn { background: #1e4870 !important; color: #fff !important; border-radius: 8rpx; }
.head { padding: 48rpx 0 24rpx; display: flex; flex-direction: column; align-items: center; background: #fff; }
.avatar { width: 140rpx; height: 140rpx; border-radius: 50%; background: #eee; }
.name { font-size: 40rpx; font-weight: 700; margin-top: 20rpx; color: #1e4870; }
.since { font-size: 24rpx; color: #666; margin-top: 8rpx; }
.since.muted { color: #bbb; }
.wallet { display: flex; gap: 16rpx; margin: 20rpx 24rpx 8rpx; }
.w-item { flex: 1; background: #1e4870; border-radius: 16rpx; padding: 24rpx; color: #fff; }
.w-lab { font-size: 22rpx; opacity: .75; }
.w-num { font-size: 40rpx; font-weight: 700; margin-top: 8rpx; }
.w-tip { font-size: 20rpx; opacity: .65; margin-top: 8rpx; }
.triple { display: flex; background: #fff; padding: 12rpx 0 36rpx; margin: 16rpx 0; }
.t-item { flex: 1; text-align: center; }
.t-ico { width: 56rpx; height: 56rpx; margin-bottom: 10rpx; }
.t-n { font-size: 28rpx; font-weight: 700; color: #1e4870; }
.menu { background: #fff; }
.menu-row {
  padding: 28rpx 32rpx;
  display: flex;
  align-items: center;
  border-bottom: 1rpx solid #f3f3f3;
}
.m-ico { width: 44rpx; height: 44rpx; margin-right: 20rpx; flex-shrink: 0; }
.m-name { flex: 1; font-size: 30rpx; color: #222; }
.en { font-size: 18rpx; color: #c0c4c8; letter-spacing: 1rpx; margin-right: 8rpx; }
.arrow { font-size: 36rpx; color: #ccc; line-height: 1; }
.edit-btn { margin-top: 16rpx; font-size: 24rpx; color: #1e4870; }
.edit-mask { position: fixed; left: 0; right: 0; top: 0; bottom: 0; background: rgba(0,0,0,.45); z-index: 30; display: flex; align-items: center; justify-content: center; }
.edit-card { width: 560rpx; background: #fff; border-radius: 24rpx; padding: 36rpx; display: flex; flex-direction: column; align-items: center; }
.edit-title { font-size: 32rpx; font-weight: 700; color: #1e4870; margin-bottom: 24rpx; }
.avatar-btn { width: 140rpx; height: 140rpx; padding: 0; border-radius: 50%; overflow: hidden; }
.avatar-btn::after { border: none; }
.edit-input { width: 100%; height: 80rpx; background: #f4f2ee; border-radius: 12rpx; margin-top: 24rpx; text-align: center; }
.save-btn { width: 100%; margin-top: 24rpx; background: #1e4870; color: #fff; }
.logout { margin: 40rpx 36rpx; text-align: center; color: #c45656; font-size: 28rpx; }
</style>
